mod baseline;mod phase;
#[path="../orbit-core/sparse.rs"]mod sparse;
use hec_native_ic::{counted,fp::Fp,jac::Curve,poly::Poly,rng::Rng,instance::factor_base};
fn main(){counted::disable();let old=include_str!("../root-pipeline/CONTROL.tsv");let old:Vec<Vec<&str>>=old.lines().skip(1).map(|l|l.split('\t').collect()).collect();println!("p\tsm\tcase\trep\tphase\tmodulus\tcounts");let mut calls=0;
 for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let fb=factor_base(&c);let base=c.place(fb[0].0,fb[0].1);let mut rng=Rng::new(2026113000^p);for sm in[1,17]{let d=c.mul(&base,sm);for case in 0..2{let k=1+rng.below(ell-1);let t=c.mul(&d,k);let mut first=None;for rep in 0..2{phase::reset();counted::reset();let report=baseline::solve(&c,&d,&t,ell,sm,false);let total=counted::snapshot();counted::disable();assert_eq!(report.k,Some(k));let stages=phase::snapshot();let mut summed=std::collections::BTreeMap::<u64,[u64;16]>::new();for((name,m),v)in &stages{let s=summed.entry(*m).or_default();for j in 0..16{s[j]+=v[j];}assert_eq!(v[8],2*v[7]+v[5]+v[6]);println!("{p}\t{sm}\t{case}\t{rep}\t{name}\t{m}\t{}",v.iter().map(u64::to_string).collect::<Vec<_>>().join(","));}assert_eq!(summed,total);for(m,v)in &total{let row=old.iter().find(|x|x[0]==p.to_string()&&x[1]==sm.to_string()&&x[2]==case.to_string()&&x[3]==rep.to_string()&&x[4]=="0"&&x[5]==m.to_string()).unwrap();let expected:Vec<u64>=row[12].split(',').map(|x|x.parse().unwrap()).collect();assert_eq!(v.as_slice(),expected.as_slice());}if let Some(ref previous)=first{assert_eq!(previous,&stages)}else{first=Some(stages)}calls+=1;}}}}
 assert_eq!(calls,24);eprintln!("calls=24 fixed_original_targets=12 all_prior_total_vectors_exact=true exclusive_phase_sum_exact=true exact_repeats=true independent_verification=false");}
